# Stage-1 structural check (F2-1 A*): the characters of Z/2^m span the same
# 2^m-dimensional space as the depth-m cylinder indicators, i.e. the character
# matrix X[j][k] = i^(j*k*4/2^m) is invertible, for m = 1, 2 (exact Gaussian
# integers). No candidate operator, no R, P, Gate 4 or Gate 5 quantity is computed.
from itertools import permutations
def gmul(a, b): return (a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0])
def gadd(a, b): return (a[0]+b[0], a[1]+b[1])
IPOW = [(1, 0), (0, 1), (-1, 0), (0, -1)]
def sign(p):
    s, seen = 1, list(p)
    for i in range(len(seen)):
        for j in range(i+1, len(seen)):
            if seen[i] > seen[j]: s = -s
    return s
def det(M):
    n, tot = len(M), (0, 0)
    for p in permutations(range(n)):
        t = (sign(p), 0)
        for i in range(n): t = gmul(t, M[i][p[i]])
        tot = gadd(tot, t)
    return tot
for m in (1, 2):
    q = 2**m
    X = [[IPOW[(j*k*(4//q)) % 4] for k in range(q)] for j in range(q)]
    real = all(e[1] == 0 for row in X for e in row)
    print(f"m={m} q={q} det={det(X)} all_real={real}")
